"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as Primitive from "@radix-ui/react-navigation-menu";
import { ArrowUpRight, ChevronDown } from "lucide-react";
import { useLayoutEffect, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { GlideHighlight, glideBox, type GlideBox } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./navigation-menu.css";

/**
 * A site header's destinations, some with a panel of links. Hover waits for
 * intent before opening, a highlight glides between items, and the frosted
 * panel follows from one item to the next by resizing in place rather than
 * closing and opening again. Every panel is reachable by keyboard: Enter or
 * ↓ opens it, Tab walks its links, Escape closes it and returns to its item.
 * Below a tablet width use a drawer instead: a flyout is a pointer pattern.
 */
export function NavigationMenu({ className, children, ...props }: ComponentProps<typeof Primitive.Root>) {
  const [root, setRoot] = useState<HTMLElement | null>(null);
  // The panel starts under its item and glides to the next one, but never past the window edge.
  useLayoutEffect(() => {
    if (!root) return;
    const anchor = root.querySelector<HTMLElement>('[data-slot="navigation-viewport-anchor"]');
    if (!anchor) return;
    let wasOpen = false;
    const place = () => {
      const viewport = anchor.querySelector<HTMLElement>('[data-slot="navigation-viewport"]');
      const trigger = root.querySelector<HTMLElement>('[data-slot="navigation-item-control"][data-state="open"]');
      if (!viewport || !trigger) {
        wasOpen = false;
        return;
      }
      const width = parseFloat(viewport.style.getPropertyValue("--radix-navigation-menu-viewport-width")) || viewport.offsetWidth;
      const box = root.getBoundingClientRect();
      const wanted = trigger.getBoundingClientRect().left - box.left - 8;
      const left = Math.max(16 - box.left, Math.min(wanted, window.innerWidth - 16 - width - box.left));
      anchor.toggleAttribute("data-instant", !wasOpen);
      anchor.style.setProperty("--nav-offset", `${Math.round(left)}px`);
      wasOpen = true;
    };
    place();
    const observer = new MutationObserver(place);
    observer.observe(root, { subtree: true, attributes: true, attributeFilter: ["data-state", "style"] });
    window.addEventListener("resize", place);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", place);
    };
  }, [root]);
  return (
    <Primitive.Root ref={setRoot} data-slot="navigation-menu" className={cn("relative z-20 flex max-w-full", className)} {...props}>
      {children}
      <div data-slot="navigation-viewport-anchor" className="absolute top-full left-0">
        <Primitive.Viewport data-slot="navigation-viewport" />
      </div>
    </Primitive.Root>
  );
}

export function NavigationMenuList({ className, children, ...props }: ComponentProps<typeof Primitive.List>) {
  const [list, setList] = useState<HTMLUListElement | null>(null);
  const [box, setBox] = useState<GlideBox | null>(null);
  // The highlight sits under the item you point at or focus, and rests on the open item otherwise.
  useLayoutEffect(() => {
    if (!list) return;
    const update = () => {
      const target =
        list.querySelector<HTMLElement>('[data-slot="navigation-item-control"][data-hovered]') ??
        list.querySelector<HTMLElement>('[data-slot="navigation-item-control"][data-state="open"]');
      setBox((current) => (target ? glideBox(target) : current ? { ...current, active: false } : null));
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(list, { subtree: true, attributes: true, attributeFilter: ["data-state", "data-hovered"] });
    return () => observer.disconnect();
  }, [list]);
  return (
    <Primitive.List
      ref={setList}
      data-slot="navigation-list"
      className={cn("relative flex items-center gap-0.5", className)}
      onPointerOver={(event) => markHover(list, event.target)}
      onPointerLeave={() => markHover(list, null)}
      onFocus={(event) => markHover(list, event.target)}
      onBlur={() => markHover(list, null)}
      {...props}
    >
      <GlideHighlight box={box} />
      {children}
    </Primitive.List>
  );
}

/* Pointer and focus position, mirrored in an attribute the observer above can watch. */
function markHover(list: HTMLElement | null, target: EventTarget | null) {
  if (!list) return;
  const control = target instanceof Element ? target.closest('[data-slot="navigation-item-control"]') : null;
  list.querySelectorAll("[data-hovered]").forEach((element) => element !== control && element.removeAttribute("data-hovered"));
  if (control && list.contains(control)) control.setAttribute("data-hovered", "");
}

export const NavigationMenuItem = Primitive.Item;

const control =
  "relative z-10 inline-flex h-9 select-none items-center gap-1 rounded-[10px] px-3 text-[13px] font-medium text-muted-foreground outline-none transition-colors duration-[var(--duration-fast)] ease-[var(--ease-out)] hover:text-foreground focus-visible:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring data-[state=open]:text-foreground data-[active]:text-foreground";

export function NavigationMenuTrigger({ className, children, ...props }: ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Trigger data-slot="navigation-item-control" className={cn(control, "cursor-default", className)} {...props}>
      {children}
      <ChevronDown aria-hidden="true" data-slot="navigation-chevron" className="size-3.5" />
    </Primitive.Trigger>
  );
}

/** A top-level destination without a panel. Pass `active` on the current page. */
export function NavigationMenuLink({ className, ...props }: ComponentProps<typeof Primitive.Link>) {
  return <Primitive.Link data-slot="navigation-item-control" className={cn(control, className)} {...props} />;
}

export function NavigationMenuContent({ className, ...props }: ComponentProps<typeof Primitive.Content>) {
  return <Primitive.Content data-slot="navigation-content" className={cn("p-2", className)} {...props} />;
}

/**
 * A link inside a panel: an optional icon, a title and one line saying what
 * is there. `external` adds an arrow and opens a new tab.
 */
export function NavigationMenuCard({
  href,
  title,
  description,
  icon,
  external = false,
  active,
  className,
}: {
  href: string;
  title: string;
  description?: string;
  icon?: ReactNode;
  external?: boolean;
  active?: boolean;
  className?: string;
}) {
  return (
    <Primitive.Link asChild active={active}>
      <a
        href={href}
        data-slot="navigation-card"
        target={external ? "_blank" : undefined}
        rel={external ? "noreferrer" : undefined}
        aria-current={active ? "page" : undefined}
        className={className}
      >
        {icon && <span data-slot="navigation-card-icon" aria-hidden="true">{icon}</span>}
        <span className="grid min-w-0 gap-0.5">
          <span className="inline-flex items-center gap-1 text-[13px] font-medium text-foreground">
            {title}
            {external && (
              <>
                <ArrowUpRight aria-hidden="true" className="size-3.5 text-muted-foreground" />
                <span className="sr-only">(opens in a new tab)</span>
              </>
            )}
          </span>
          {description && <span className="text-xs leading-[18px] text-muted-foreground">{description}</span>}
        </span>
      </a>
    </Primitive.Link>
  );
}

/**
 * Lays a panel out in labelled columns, with an optional featured cell on
 * the end (a launch, a guide). Columns stack in a narrow viewport.
 */
export function NavigationMenuPanel({
  columns,
  featured,
  className,
}: {
  columns: readonly { title?: string; links: readonly ComponentProps<typeof NavigationMenuCard>[] }[];
  featured?: ReactNode;
  className?: string;
}) {
  return (
    <div data-slot="navigation-panel" data-featured={featured ? "" : undefined} style={{ "--nav-columns": columns.length } as CSSProperties} className={className}>
      {columns.map((column, index) => (
        <div key={column.title ?? index} className="grid content-start gap-0.5">
          {column.title && <p data-slot="navigation-panel-title">{column.title}</p>}
          <ul className="grid gap-0.5">
            {column.links.map((link) => (
              <li key={link.href + link.title}>
                <NavigationMenuCard {...link} />
              </li>
            ))}
          </ul>
        </div>
      ))}
      {featured && <div data-slot="navigation-featured">{featured}</div>}
    </div>
  );
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}

/* navigation-menu.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

[data-slot="navigation-viewport"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}
@layer components {
  /* Navigation menu */
  [data-slot="navigation-list"] { list-style: none; margin: 0; padding: 0; }
  [data-slot="navigation-list"] > [data-slot="glide-highlight"] { border-radius: 12px; }
  [data-slot="navigation-chevron"] { transition: rotate var(--duration-normal) var(--ease-settle); }
  [data-state="open"] > [data-slot="navigation-chevron"] { rotate: -180deg; }
  [data-slot="navigation-viewport-anchor"] { translate: var(--nav-offset, 0) 0; transition: translate var(--duration-deliberate) var(--ease-out); }
  [data-slot="navigation-viewport-anchor"][data-instant] { transition: none; }
  [data-slot="navigation-viewport"] {
    position: relative; margin-top: 8px; overflow: hidden;
    width: var(--radix-navigation-menu-viewport-width); height: var(--radix-navigation-menu-viewport-height);
    max-width: calc(100vw - 2rem);
    border: 1px solid var(--border); border-radius: 16px;
    transform-origin: top left;
    transition: width var(--duration-deliberate) var(--ease-out), height var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="navigation-viewport"][data-state="open"] { animation: caliper-dialog-enter var(--duration-normal) var(--ease-out); }
  [data-slot="navigation-viewport"][data-state="closed"] { animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards; }
  [data-slot="navigation-content"] { position: absolute; top: 0; left: 0; width: max-content; max-width: calc(100vw - 2rem); }
  [data-slot="navigation-content"][data-motion="from-start"] { animation: caliper-nav-panel-from-start var(--duration-deliberate) var(--ease-out); }
  [data-slot="navigation-content"][data-motion="from-end"] { animation: caliper-nav-panel-from-end var(--duration-deliberate) var(--ease-out); }
  [data-slot="navigation-content"][data-motion="to-start"] { animation: caliper-nav-panel-to-start var(--duration-fast) var(--ease-in) forwards; }
  [data-slot="navigation-content"][data-motion="to-end"] { animation: caliper-nav-panel-to-end var(--duration-fast) var(--ease-in) forwards; }
  [data-slot="navigation-panel"] { display: grid; gap: 4px 12px; width: min(calc(var(--nav-columns) * 260px), calc(100vw - 3rem)); grid-template-columns: repeat(var(--nav-columns), minmax(0, 1fr)); }
  [data-slot="navigation-panel"][data-featured] { width: min(calc(var(--nav-columns) * 260px + 240px), calc(100vw - 3rem)); grid-template-columns: repeat(var(--nav-columns), minmax(0, 1fr)) 228px; }
  @media (max-width: 720px) { [data-slot="navigation-panel"], [data-slot="navigation-panel"][data-featured] { grid-template-columns: minmax(0, 1fr); width: calc(100vw - 3rem); } }
  [data-slot="navigation-panel-title"] { margin: 6px 10px 4px; font-size: 12px; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted-foreground); }
  [data-slot="navigation-panel"] ul { list-style: none; margin: 0; padding: 0; }
  [data-slot="navigation-card"] {
    display: flex; align-items: flex-start; gap: 10px; padding: 9px 10px; border-radius: 12px; text-decoration: none; outline: none;
    transition: background-color var(--duration-fast) var(--ease-out);
  }
  [data-slot="navigation-card"]:hover, [data-slot="navigation-card"]:focus-visible { background: var(--muted); }
  [data-slot="navigation-card"]:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
  [data-slot="navigation-card"][aria-current="page"] { background: var(--selected); }
  [data-slot="navigation-card-icon"] { display: grid; flex: none; place-items: center; width: 32px; height: 32px; border-radius: 8px; background: var(--raised); box-shadow: var(--shadow-raised); color: var(--foreground); }
  [data-slot="navigation-card-icon"] svg { width: 16px; height: 16px; }
  [data-slot="navigation-featured"] { display: grid; align-content: start; justify-items: start; gap: 6px; min-height: 100%; padding: 14px; border-radius: 12px; background: var(--surface); box-shadow: inset 0 0 0 1px var(--border); }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="navigation-viewport"], [data-slot="navigation-content"] { animation: none !important; }
  }
  /* Wide rows (accordion, sidebar, donut legend) set their pressed fill with an active: utility next to their hover:
     utility, since utilities outrank this layer. The navigation menu trigger has none, so it is set here. */
  [data-slot="navigation-item-control"]:active:not(:disabled):not([aria-disabled="true"]) {
    background-color: var(--raised-press);
  }
}
@keyframes caliper-nav-panel-from-start { from { opacity: 0; translate: -16px 0; } to { opacity: 1; translate: 0 0; } }
@keyframes caliper-nav-panel-from-end { from { opacity: 0; translate: 16px 0; } to { opacity: 1; translate: 0 0; } }
@keyframes caliper-nav-panel-to-start { to { opacity: 0; translate: -16px 0; } }
@keyframes caliper-nav-panel-to-end { to { opacity: 0; translate: 16px 0; } }
